from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RUNTIME = ROOT / "EngineData/Frontend/RustApp/src-tauri/src/commands/helper_bridge_runtime.rs"
NEXT = ROOT / "docs/knowledge/next-action.md"


def read(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def write(path: Path, text: str) -> None:
    path.write_text(text, encoding="utf-8", newline="\n")


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one match, found {count}")
    return text.replace(old, new, 1)


def source() -> None:
    text = read(RUNTIME)
    text = replace_once(
        text,
        "use std::time::{Duration, SystemTime, UNIX_EPOCH};\n",
        "use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};\n",
        "scheduler monotonic clock import",
    )
    text = replace_once(
        text,
        "pub const WORKER_FALLBACK_RESPONSE_DEADLINE_MS: u128 = WORKER_STATUS_RESPONSE_DEADLINE_MS;\n",
        '''pub const WORKER_FALLBACK_RESPONSE_DEADLINE_MS: u128 = WORKER_STATUS_RESPONSE_DEADLINE_MS;\n\npub const HELPER_SCHEDULER_TOTAL_ADMISSION_CAP: u32 = 8;\npub const HELPER_SCHEDULER_MEETING_OUTBOUND_WAIT_MS: u64 = 120_000;\npub const HELPER_SCHEDULER_MEETING_INCOMING_WAIT_MS: u64 = 30_000;\npub const HELPER_SCHEDULER_TEXT_WAIT_MS: u64 = 15_000;\npub const HELPER_SCHEDULER_DIAGNOSTIC_WAIT_MS: u64 = 5_000;\n''',
        "scheduler bounds",
    )
    old_priority_impl = '''impl HelperTaskPriority {\n    pub fn label(self) -> &'static str {\n        match self {\n            Self::MeetingOutbound => "meeting_outbound",\n            Self::MeetingIncoming => "meeting_incoming",\n            Self::Text => "text",\n            Self::Diagnostic => "diagnostic",\n        }\n    }\n}\n'''
    new_priority_impl = '''impl HelperTaskPriority {\n    pub fn label(self) -> &'static str {\n        match self {\n            Self::MeetingOutbound => "meeting_outbound",\n            Self::MeetingIncoming => "meeting_incoming",\n            Self::Text => "text",\n            Self::Diagnostic => "diagnostic",\n        }\n    }\n\n    fn scheduler_wait_deadline_ms(self) -> u64 {\n        match self {\n            Self::MeetingOutbound => HELPER_SCHEDULER_MEETING_OUTBOUND_WAIT_MS,\n            Self::MeetingIncoming => HELPER_SCHEDULER_MEETING_INCOMING_WAIT_MS,\n            Self::Text => HELPER_SCHEDULER_TEXT_WAIT_MS,\n            Self::Diagnostic => HELPER_SCHEDULER_DIAGNOSTIC_WAIT_MS,\n        }\n    }\n\n    fn scheduler_admission_limit(self) -> u32 {\n        match self {\n            Self::MeetingOutbound => HELPER_SCHEDULER_TOTAL_ADMISSION_CAP,\n            Self::MeetingIncoming => HELPER_SCHEDULER_TOTAL_ADMISSION_CAP.saturating_sub(1),\n            Self::Text => HELPER_SCHEDULER_TOTAL_ADMISSION_CAP.saturating_sub(2),\n            Self::Diagnostic => HELPER_SCHEDULER_TOTAL_ADMISSION_CAP.saturating_sub(3),\n        }\n    }\n}\n'''
    text = replace_once(text, old_priority_impl, new_priority_impl, "priority scheduler policy")
    text = replace_once(
        text,
        '''fn scheduler_can_enter(state: &HelperSchedulerState, priority: HelperTaskPriority) -> bool {\n''',
        '''fn scheduler_total_admitted(state: &HelperSchedulerState) -> u32 {\n    let active = if state.active { 1_u32 } else { 0_u32 };\n    active\n        .saturating_add(state.waiting_meeting_outbound)\n        .saturating_add(state.waiting_meeting_incoming)\n        .saturating_add(state.waiting_text)\n        .saturating_add(state.waiting_diagnostic)\n}\n\nfn scheduler_can_admit(state: &HelperSchedulerState, priority: HelperTaskPriority) -> bool {\n    scheduler_total_admitted(state) < priority.scheduler_admission_limit()\n}\n\nfn scheduler_wait_deadline_error(\n    priority: HelperTaskPriority,\n    wait_deadline: Duration,\n) -> String {\n    format!(\n        "helper_scheduler:wait_deadline_exceeded:{}:{}ms",\n        priority.label(),\n        wait_deadline.as_millis()\n    )\n}\n\nfn scheduler_can_enter(state: &HelperSchedulerState, priority: HelperTaskPriority) -> bool {\n''',
        "scheduler admission helpers",
    )
    old_acquire = '''pub fn acquire_helper_task_permit(\n    priority: HelperTaskPriority,\n) -> Result<HelperTaskPermit, String> {\n    let (lock, wake) = scheduler();\n    let mut state = lock\n        .lock()\n        .map_err(|_| "helper_scheduler:lock_poisoned".to_string())?;\n    scheduler_waiting_increment(&mut state, priority);\n\n    while !scheduler_can_enter(&state, priority) {\n        state = wake\n            .wait(state)\n            .map_err(|_| "helper_scheduler:wait_lock_poisoned".to_string())?;\n    }\n\n    scheduler_waiting_decrement(&mut state, priority);\n    state.active = true;\n    state.next_request_sequence = state.next_request_sequence.saturating_add(1);\n    Ok(HelperTaskPermit {\n        request_id: format!("helper-{}", state.next_request_sequence),\n        priority,\n    })\n}\n'''
    new_acquire = '''fn acquire_helper_task_permit_with_wait_deadline(\n    priority: HelperTaskPriority,\n    wait_deadline: Duration,\n) -> Result<HelperTaskPermit, String> {\n    let (lock, wake) = scheduler();\n    let mut state = lock\n        .lock()\n        .map_err(|_| "helper_scheduler:lock_poisoned".to_string())?;\n\n    if !scheduler_can_admit(&state, priority) {\n        return Err(format!(\n            "helper_scheduler:admission_capacity_exceeded:{}:total={}:limit={}",\n            priority.label(),\n            scheduler_total_admitted(&state),\n            priority.scheduler_admission_limit()\n        ));\n    }\n\n    scheduler_waiting_increment(&mut state, priority);\n    let wait_started = Instant::now();\n\n    while !scheduler_can_enter(&state, priority) {\n        let remaining = wait_deadline.saturating_sub(wait_started.elapsed());\n        if remaining.is_zero() {\n            scheduler_waiting_decrement(&mut state, priority);\n            wake.notify_all();\n            return Err(scheduler_wait_deadline_error(priority, wait_deadline));\n        }\n\n        let (next_state, wait_result) = match wake.wait_timeout(state, remaining) {\n            Ok(value) => value,\n            Err(poisoned) => {\n                let (mut poisoned_state, _) = poisoned.into_inner();\n                scheduler_waiting_decrement(&mut poisoned_state, priority);\n                wake.notify_all();\n                return Err("helper_scheduler:wait_lock_poisoned".to_string());\n            }\n        };\n        state = next_state;\n\n        if wait_result.timed_out() && !scheduler_can_enter(&state, priority) {\n            scheduler_waiting_decrement(&mut state, priority);\n            wake.notify_all();\n            return Err(scheduler_wait_deadline_error(priority, wait_deadline));\n        }\n    }\n\n    scheduler_waiting_decrement(&mut state, priority);\n    state.active = true;\n    state.next_request_sequence = state.next_request_sequence.saturating_add(1);\n    Ok(HelperTaskPermit {\n        request_id: format!("helper-{}", state.next_request_sequence),\n        priority,\n    })\n}\n\npub fn acquire_helper_task_permit(\n    priority: HelperTaskPriority,\n) -> Result<HelperTaskPermit, String> {\n    acquire_helper_task_permit_with_wait_deadline(\n        priority,\n        Duration::from_millis(priority.scheduler_wait_deadline_ms()),\n    )\n}\n'''
    text = replace_once(text, old_acquire, new_acquire, "bounded scheduler acquisition")
    scheduler_tests = '''#[cfg(test)]\nmod scheduler_policy_tests {\n    use super::*;\n\n    fn reset_scheduler() {\n        let (lock, wake) = scheduler();\n        let mut state = lock.lock().expect("scheduler test lock");\n        *state = HelperSchedulerState::default();\n        wake.notify_all();\n    }\n\n    #[test]\n    fn scheduler_policy_preserves_priority_and_reserved_admission_headroom() {\n        assert!(\n            HelperTaskPriority::MeetingOutbound.scheduler_wait_deadline_ms()\n                > HelperTaskPriority::MeetingIncoming.scheduler_wait_deadline_ms()\n        );\n        assert!(\n            HelperTaskPriority::MeetingIncoming.scheduler_wait_deadline_ms()\n                > HelperTaskPriority::Text.scheduler_wait_deadline_ms()\n        );\n        assert!(\n            HelperTaskPriority::Text.scheduler_wait_deadline_ms()\n                > HelperTaskPriority::Diagnostic.scheduler_wait_deadline_ms()\n        );\n\n        let mut state = HelperSchedulerState::default();\n        state.waiting_meeting_outbound = 1;\n        assert!(scheduler_can_enter(\n            &state,\n            HelperTaskPriority::MeetingOutbound\n        ));\n        assert!(!scheduler_can_enter(\n            &state,\n            HelperTaskPriority::MeetingIncoming\n        ));\n        assert!(!scheduler_can_enter(&state, HelperTaskPriority::Text));\n        assert!(!scheduler_can_enter(\n            &state,\n            HelperTaskPriority::Diagnostic\n        ));\n\n        state.waiting_meeting_outbound = 0;\n        state.waiting_meeting_incoming = 1;\n        assert!(scheduler_can_enter(\n            &state,\n            HelperTaskPriority::MeetingIncoming\n        ));\n        assert!(!scheduler_can_enter(&state, HelperTaskPriority::Text));\n        assert!(!scheduler_can_enter(\n            &state,\n            HelperTaskPriority::Diagnostic\n        ));\n\n        state.waiting_meeting_incoming = 0;\n        state.waiting_text = 1;\n        assert!(scheduler_can_enter(&state, HelperTaskPriority::Text));\n        assert!(!scheduler_can_enter(\n            &state,\n            HelperTaskPriority::Diagnostic\n        ));\n\n        state = HelperSchedulerState::default();\n        state.active = true;\n        state.waiting_diagnostic = HelperTaskPriority::Diagnostic\n            .scheduler_admission_limit()\n            .saturating_sub(1);\n        assert_eq!(\n            scheduler_total_admitted(&state),\n            HelperTaskPriority::Diagnostic.scheduler_admission_limit()\n        );\n        assert!(!scheduler_can_admit(\n            &state,\n            HelperTaskPriority::Diagnostic\n        ));\n        assert!(scheduler_can_admit(&state, HelperTaskPriority::Text));\n        assert!(scheduler_can_admit(\n            &state,\n            HelperTaskPriority::MeetingIncoming\n        ));\n        assert!(scheduler_can_admit(\n            &state,\n            HelperTaskPriority::MeetingOutbound\n        ));\n        assert_eq!(\n            HelperTaskPriority::MeetingOutbound.scheduler_admission_limit(),\n            HELPER_SCHEDULER_TOTAL_ADMISSION_CAP\n        );\n    }\n\n    #[test]\n    fn scheduler_capacity_rejection_does_not_add_waiting_callers() {\n        reset_scheduler();\n        {\n            let (lock, _) = scheduler();\n            let mut state = lock.lock().expect("scheduler test lock");\n            state.active = true;\n            state.waiting_diagnostic = HelperTaskPriority::Diagnostic\n                .scheduler_admission_limit()\n                .saturating_sub(1);\n        }\n\n        let error = match acquire_helper_task_permit_with_wait_deadline(\n            HelperTaskPriority::Diagnostic,\n            Duration::from_millis(1),\n        ) {\n            Ok(_) => panic!("diagnostic request should be rejected at its admission limit"),\n            Err(error) => error,\n        };\n        assert!(error.starts_with(\n            "helper_scheduler:admission_capacity_exceeded:diagnostic:"\n        ));\n\n        let (lock, _) = scheduler();\n        let state = lock.lock().expect("scheduler test lock");\n        assert_eq!(\n            scheduler_total_admitted(&state),\n            HelperTaskPriority::Diagnostic.scheduler_admission_limit()\n        );\n        drop(state);\n        reset_scheduler();\n    }\n\n    #[test]\n    fn scheduler_wait_deadline_cleans_counter_and_releases_lower_priority_blocking() {\n        reset_scheduler();\n        let active = acquire_helper_task_permit_with_wait_deadline(\n            HelperTaskPriority::MeetingOutbound,\n            Duration::from_millis(50),\n        )\n        .expect("outbound scheduler permit");\n\n        let waiter = thread::spawn(|| {\n            acquire_helper_task_permit_with_wait_deadline(\n                HelperTaskPriority::Text,\n                Duration::from_millis(25),\n            )\n        });\n        let error = match waiter.join().expect("scheduler waiter thread") {\n            Ok(_) => panic!("text request should time out while worker remains active"),\n            Err(error) => error,\n        };\n        assert_eq!(error, "helper_scheduler:wait_deadline_exceeded:text:25ms");\n\n        {\n            let (lock, _) = scheduler();\n            let state = lock.lock().expect("scheduler test lock");\n            assert!(state.active);\n            assert_eq!(state.waiting_text, 0);\n            assert_eq!(state.waiting_meeting_outbound, 0);\n            assert_eq!(state.waiting_meeting_incoming, 0);\n            assert_eq!(state.waiting_diagnostic, 0);\n        }\n\n        drop(active);\n        {\n            let (lock, _) = scheduler();\n            let state = lock.lock().expect("scheduler test lock");\n            assert!(!state.active);\n        }\n        reset_scheduler();\n    }\n}\n\n'''
    text = replace_once(
        text,
        "#[cfg(test)]\nmod deadline_policy_tests {\n",
        scheduler_tests + "#[cfg(test)]\nmod deadline_policy_tests {\n",
        "scheduler policy tests",
    )
    write(RUNTIME, text)


def closure() -> None:
    text = read(NEXT)
    old = '''## Current Mode\n\n**Maintenance / Backend Hardening Wave A** — Waves A1-A3 are source/proof closed. Continue one bounded hardening slice at a time before P2.3.\n\n## Next Step — Backend Hardening Wave A4: Bounded Scheduler Admission / Wait\n\nBound the existing single-worker priority scheduler so waiting callers cannot accumulate indefinitely: add a small total admission cap and priority-aware wait deadline while preserving `Meeting outbound > Meeting incoming > Text > diagnostics`. Requests that cannot be admitted in time must return a truthful scheduler blocker without spawning another worker or retry loop. Keep A4 limited to scheduler admission/wait and targeted tests; do not mix stderr lifecycle (A5), readiness compatibility (A6), Python locking/assets (A7), model execution, or audio-route work.\n'''
    new = '''## Backend Hardening Wave A4 — CLOSED\n\nThe existing single-worker scheduler now has bounded admission and bounded waiting instead of allowing callers to accumulate indefinitely. Total scheduler occupancy is capped at 8 active/waiting requests, with reserved headroom so lower-priority diagnostics/Text/incoming work cannot consume the last admission slots needed by higher-priority work. Execution order remains `Meeting outbound > Meeting incoming > Text > diagnostics`.\n\nScheduler wait is also priority-bounded: Meeting outbound 120s, optional Meeting incoming 30s, Text 15s, and diagnostics 5s. A request rejected at its admission limit returns `helper_scheduler:admission_capacity_exceeded:*`; a caller that cannot obtain the worker before its wait ceiling returns `helper_scheduler:wait_deadline_exceeded:*`. Timeout cleanup removes that caller from the relevant waiting counter and wakes the scheduler so a departed higher-priority waiter cannot continue blocking lower-priority work. No second worker, retry loop, watchdog, or parallel scheduler owner was added.\n\nRemote Windows/source proof for this slice passed:\n\n```text\nRust scheduler policy/admission/wait tests -> PASS\ncargo check                                -> PASS\ncanonical npm ci                           -> PASS\nTauri release build --no-bundle            -> PASS\n```\n\nNo helper stderr lifecycle change, readiness compatibility cleanup, Python dependency locking/assets work, model execution, audio-route execution, or user-local-PC testing occurred in Wave A4.\n\n## Current Mode\n\n**Maintenance / Backend Hardening Wave A** — Waves A1-A4 are source/proof closed. Continue one bounded hardening slice at a time before P2.3.\n\n## Next Step — Backend Hardening Wave A5: Bounded / Redacted Helper stderr Lifecycle\n\nReconcile helper stderr with the existing bounded/redacted logging policy: stop treating raw worker stderr as an unbounded append-only side channel, and make its logger lifecycle terminate with the owned helper process. Keep A5 limited to stderr privacy/disk/lifecycle ownership and targeted proof; do not mix readiness compatibility (A6), Python locking/assets (A7), model execution, scheduler redesign, or audio-route work.\n'''
    text = replace_once(text, old, new, "A4 closure and next step")
    write(NEXT, text)


if __name__ == "__main__":
    if len(sys.argv) != 2 or sys.argv[1] not in {"source", "closure"}:
        raise SystemExit("usage: backend_wave_a4_patch.py source|closure")
    source() if sys.argv[1] == "source" else closure()
